<script setup lang="ts">
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';import {onBeforeRouteLeave,useRoute} from 'vue-router';import {api} from '../lib/api';import {auth} from '../stores/auth';import {notify} from '../stores/notices';import {errorMessage} from '../lib/errors';import type {Project} from '../lib/types';import type {MediaAsset} from '../lib/media';import {defaultPages,pageNames,applyPage,publicPath,type PageContent,type ContentBlock} from '../lib/pages';import PublicHero from '../components/PublicHero.vue';import ContentBlocks from '../components/ContentBlocks.vue';import ImagePicker from '../components/ImagePicker.vue';import LinkFields from '../components/LinkFields.vue';import Icon from '../components/Icon.vue';import LoadState from '../components/LoadState.vue';
interface Edition {draft:PageContent;published:PageContent;revision:number;published_revision:number;history:{revision:number;content:PageContent}[]}
const route=useRoute(),initial=String(route.query.page||'agl/home');const selected=ref(defaultPages[initial]?initial:'agl/home'),active=ref(selected.value);const isNav=computed(()=>active.value.endsWith('/navigation'));const isUtility=computed(()=>isNav.value||active.value==='agl/news');const site=computed(()=>active.value.split('/')[0]);const form=reactive<PageContent>(JSON.parse(JSON.stringify(defaultPages[active.value])));const projectChoices=ref<Project[]>([]);const edition=ref<Edition|null>(null),media=ref<MediaAsset[]>([]),loading=ref(true),busy=ref(false),error=ref(''),actionError=ref(''),snapshot=ref(''),localRecovery=ref<PageContent|null>(null);const dirty=computed(()=>JSON.stringify(form)!==snapshot.value);let account=auth.profile?.id||auth.access?.account_id;const backupKey=()=>account?'agl.page-draft.'+account+'.'+active.value:'';let backupTimer:ReturnType<typeof setTimeout>;
watch(form,()=>{clearTimeout(backupTimer);backupTimer=setTimeout(()=>{if(!dirty.value||!edition.value||!backupKey())return;try{sessionStorage.setItem(backupKey(),JSON.stringify({revision:edition.value.revision,content:form}));}catch{}},600);},{deep:true});
async function load(){account||=auth.profile?.id||auth.access?.account_id;const key=active.value;loading.value=true;error.value='';localRecovery.value=null;try{const value=await api<Edition>('/workspace/site-content/'+key,{private:true});if(key!==active.value)return;edition.value=value;Object.assign(form,JSON.parse(JSON.stringify({...defaultPages[key],...value.draft})));if(form.hero_media_id){form.hero_image='media:'+form.hero_media_id;form.hero_media_id=null;}snapshot.value=JSON.stringify(form);media.value=(await api<{items:MediaAsset[]}>('/media?limit=50')).items;projectChoices.value=(await api<{items:Project[]}>('/projects?limit=50')).items;try{const local=JSON.parse(sessionStorage.getItem(backupKey())||'null');if(local?.content&&JSON.stringify(local.content)!==snapshot.value)localRecovery.value=local.content;}catch{}}catch(e){error.value=errorMessage(e);}finally{if(key===active.value)loading.value=false;}}
function choose(){if(dirty.value&&!window.confirm('Есть несохранённые изменения. Переключить страницу?')){selected.value=active.value;return;}active.value=selected.value;edition.value=null;actionError.value='';void load();}
async function save(publish=false){if(busy.value||!edition.value)return;busy.value=true;actionError.value='';const sent=JSON.parse(JSON.stringify(form));sent.hero_media_id=null;const fingerprint=JSON.stringify(form);try{if(dirty.value||!edition.value.revision){edition.value=await api<Edition>('/workspace/site-content/'+active.value,{private:true,method:'PUT',body:{expected_revision:edition.value.revision,content:sent}});snapshot.value=fingerprint;}if(publish){if(JSON.stringify(form)!==fingerprint){notify('Черновик сохранён. Новые изменения ещё остаются в форме.');return;}edition.value=await api<Edition>('/workspace/site-content/'+active.value+'/publish',{private:true,method:'POST',body:{expected_revision:edition.value.revision}});applyPage(active.value,edition.value.published);}if(!dirty.value){try{sessionStorage.removeItem(backupKey());}catch{}localRecovery.value=null;}notify(publish?'Страница опубликована':'Черновик сохранён на сервере');}catch(e){actionError.value=errorMessage(e);}finally{busy.value=false;}}
function addBlock(){if(form.sections.length<12)form.sections.push({type:'text',eyebrow:'',title:'Новый раздел',body:'',image:'',alt:'',caption:'',images:[],links:[]});}
function move(index:number,delta:number){const target=index+delta;if(target<0||target>=form.sections.length)return;const value=form.sections.splice(index,1)[0];form.sections.splice(target,0,value);}
function addLink(list:any[]){if(list.length<8)list.push({label:'',url:''});}
function addGallery(block:ContentBlock){block.images||=[];if(block.images.length<8)block.images.push({src:'',alt:'',caption:''});}
function leaving(event:BeforeUnloadEvent){if(dirty.value&&edition.value){event.preventDefault();event.returnValue='';}}window.addEventListener('beforeunload',leaving);onBeforeUnmount(()=>{clearTimeout(backupTimer);window.removeEventListener('beforeunload',leaving);});onBeforeRouteLeave(()=>!edition.value||!dirty.value||window.confirm('Есть несохранённые изменения. Выйти?'));watch(()=>auth.access?.owner,value=>{if(value)void load();},{immediate:true});
</script>
<template><div v-if="auth.access?.owner"><header class="workspace-heading"><span class="eyebrow">СТРАНИЦЫ И МАТЕРИАЛЫ</span><h1>Содержимое сайтов</h1></header><label class="content-page-select">Страница<select v-model="selected" :disabled="busy" @change="choose"><optgroup v-for="group in ['agl','personal']" :key="group" :label="group==='agl'?'Alex Game Lab':'Портфолио'"><option v-for="key in Object.keys(pageNames).filter(k=>k.startsWith(group+'/'))" :key="key" :value="key">{{pageNames[key]}}</option></optgroup></select></label><LoadState :loading="loading" :error="error" @retry="load"><div v-if="localRecovery" class="notice"><p>Есть локальная копия несохранённых изменений. Серверная версия {{edition?.revision}}.</p><button class="button secondary" @click="Object.assign(form,localRecovery);localRecovery=null">Вернуть текст в форму</button></div><form @submit.prevent="save(true)"><div class="content-grid"><section class="panel content-fields"><div class="panel-heading"><h2>{{pageNames[active]}}</h2><span class="badge">Версия {{edition?.revision||0}}</span></div><label>Заголовок<input v-model="form.title" required minlength="3" maxlength="120"/></label><label v-if="!isNav">Описание<textarea v-model="form.intro" required maxlength="500" rows="4"/></label><label v-if="!isUtility">Короткая подпись<input v-model="form.eyebrow" maxlength="80"/></label><ImagePicker v-if="!isUtility" v-model="form.hero_image" label="Главное изображение" :media="media" :site="site"/><ImagePicker v-if="!isUtility" v-model="form.hero_mobile_image" label="Изображение для телефона" :media="media" :site="site"/><label v-if="!isUtility">Описание изображения<input v-model="form.hero_alt" maxlength="300"/></label><a class="inline-link" href="/workspace/media/">Открыть медиатеку ↗</a><label v-if="active==='agl/home'">Выбранный проект<select v-model="form.featured_project"><option v-for="project in projectChoices" :key="project.slug" :value="project.slug">{{project.title}}</option></select></label><details><summary>Кнопки и ссылки</summary><LinkFields v-if="!isUtility" :link="form.primary" label="Основная кнопка"/><LinkFields v-if="!isUtility" :link="form.secondary" label="Дополнительная кнопка"/><template v-if="active==='agl/home'"><label>Подпись канала<input v-model="form.channel_label" maxlength="50" required/></label><label>Ссылка канала<input v-model="form.channel_url" type="url" maxlength="300" required/></label></template><div v-for="(link,index) in form.links" :key="index"><LinkFields :link="link" :label="'Пункт '+(index+1)"/><button type="button" class="text-button" @click="form.links.splice(index,1)">Убрать пункт</button></div><button type="button" class="button secondary" :disabled="form.links.length>=8" @click="addLink(form.links)">Добавить пункт</button><label>Подпись подвала<textarea v-model="form.footer_note" rows="2" maxlength="300"/></label></details><details v-if="!isNav"><summary>Превью ссылки и поиск</summary><label>Заголовок для ссылки<input v-model="form.seo_title" maxlength="160"/></label><label>Описание для ссылки<textarea v-model="form.seo_description" maxlength="300" rows="3"/></label><ImagePicker v-model="form.seo_image" label="Изображение для ссылки" :media="media" :site="site"/><p class="field-note">Опубликованный HTML-снимок обновляется сразу. Метаданные основного адреса сохраняются также в статическом выпуске сайта.</p></details></section><aside class="panel page-edition-preview"><p class="eyebrow">ПРЕДПРОСМОТР СОДЕРЖИМОГО</p><div class="public-site"><template v-if="isNav"><h2>{{form.title}}</h2><p>{{form.footer_note}}</p><p v-for="link in form.links" :key="link.url">{{link.label}} · {{link.url}}</p></template><template v-else-if="active==='agl/news'"><h2>{{form.seo_title||form.title}}</h2><p>{{form.seo_description||form.intro}}</p><p class="field-note">В ленте первым отображается список публикаций. Эти поля управляют метаданными.</p></template><PublicHero v-else :page="form" :site="site" preview/><ContentBlocks v-if="active!=='agl/news'" :blocks="form.sections" :site="site" preview/></div><a :href="publicPath(active)" target="_blank" rel="noopener" class="inline-link">Открыть опубликованную страницу ↗</a><a :href="'https://api.alexgamelab.ru/v1/previews/'+active" target="_blank" rel="noopener" class="inline-link">Опубликованный снимок для ссылки ↗</a></aside></div>
<section v-if="active!=='agl/news'" class="panel content-fields"><div class="panel-heading"><h2>Разделы страницы</h2><button type="button" class="button secondary" :disabled="form.sections.length>=12" @click="addBlock"><Icon name="plus"/>Добавить раздел</button></div><article v-for="(block,index) in form.sections" :key="index" class="content-block-editor"><div class="panel-heading"><h3>Раздел {{index+1}}</h3><div class="button-row"><button type="button" class="button secondary" :disabled="index===0" @click="move(index,-1)" aria-label="Переместить раздел вверх">↑</button><button type="button" class="button secondary" :disabled="index===form.sections.length-1" @click="move(index,1)" aria-label="Переместить раздел вниз">↓</button><button type="button" class="button secondary" @click="form.sections.splice(index,1)">Убрать</button></div></div><label>Тип раздела<select v-model="block.type"><option value="text">Текст</option><option v-if="!isNav" value="image">Текст и изображение</option><option v-if="!isNav" value="gallery">Галерея</option><option v-if="!isNav" value="project">Блок проекта</option><option value="links">Ссылки</option></select></label><div class="form-columns"><label>Заголовок раздела<input v-model="block.title" maxlength="160"/></label><label>Короткая подпись раздела<input v-model="block.eyebrow" maxlength="80"/></label></div><label>Текст раздела<textarea v-model="block.body" rows="5" maxlength="5000"/></label><ImagePicker v-if="!isNav" v-model="block.image" label="Изображение раздела" :media="media" :site="site"/><div v-if="!isNav" class="form-columns"><label>Описание изображения<input v-model="block.alt" maxlength="300"/></label><label>Подпись под изображением<input v-model="block.caption" maxlength="300"/></label></div><template v-if="block.type==='gallery'"><div v-for="(item,n) in block.images" :key="n" class="content-block-editor"><ImagePicker v-model="item.src" :label="'Изображение '+(n+1)" :media="media" :site="site"/><div class="form-columns"><label>Описание<input v-model="item.alt" maxlength="300"/></label><label>Подпись<input v-model="item.caption" maxlength="300"/></label></div><button type="button" class="text-button" @click="block.images?.splice(n,1)">Убрать изображение</button></div><button type="button" class="button secondary" @click="addGallery(block)">Добавить изображение</button></template><div v-for="(link,n) in block.links" :key="n"><LinkFields :link="link" :label="'Ссылка '+(n+1)"/><button type="button" class="text-button" @click="block.links?.splice(n,1)">Убрать ссылку</button></div><button type="button" class="button secondary" @click="block.links||=[];addLink(block.links)">Добавить ссылку</button></article></section>
<p v-if="actionError" class="notice notice-error" role="alert">{{actionError}} Текст остаётся в форме и локальной копии.</p><div class="content-actions-v2"><p role="status">{{dirty?'Есть несохранённые изменения':!edition?.revision?'Исходная редакция':edition.revision===edition.published_revision?'Опубликовано':'Черновик сохранён на сервере'}} · опубликована версия {{edition?.published_revision||0}}</p><div class="button-row"><button type="button" class="button secondary" :disabled="busy" @click="save(false)">Сохранить черновик</button><button class="button" :disabled="busy">{{busy?'Сохраняем…':'Опубликовать'}}</button></div></div></form><section v-if="edition?.history.length" class="panel edition-history"><h2>Предыдущие публикации</h2><div v-for="(entry,index) in edition.history" :key="index" class="recent-row"><div><strong>{{entry.content.title}}</strong><p>Версия {{entry.revision}}</p></div><button class="button secondary" :disabled="busy" @click="Object.assign(form,JSON.parse(JSON.stringify(entry.content)))">Вернуть в черновик</button></div></section></LoadState></div><p v-else class="notice">Управление содержимым доступно Owner.</p></template>
